hints:
```
for each color C:
    find its bounding box in targetGrid
    for each cell in C's bounding box:
        if cell color D != C:
            add edge C -> D
return true if graph has no cycles, else false
```

code.cpp:
class Solution {
public:
    bool isPrintable(vector<vector<int>>& targetGrid) {
        int m = targetGrid.size();
        int n = targetGrid[0].size();

        int min_r[61], max_r[61], min_c[61], max_c[61];
        for (int i = 0; i < 61; ++i) {
            min_r[i] = 61;
            max_r[i] = -1;
            min_c[i] = 61;
            max_c[i] = -1;
        }

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                int c = targetGrid[i][j];
                min_r[c] = min(min_r[c], i);
                max_r[c] = max(max_r[c], i);
                min_c[c] = min(min_c[c], j);
                max_c[c] = max(max_c[c], j);
            }
        }

        bool adj[61][61] = {false};
        for (int c = 1; c <= 60; ++c) {
            if (max_r[c] == -1) continue;
            for (int i = min_r[c]; i <= max_r[c]; ++i) {
                for (int j = min_c[c]; j <= max_c[c]; ++j) {
                    if (targetGrid[i][j] != c) {
                        adj[c][targetGrid[i][j]] = true;
                    }
                }
            }
        }

        int in_degree[61] = {0};
        for (int u = 1; u <= 60; ++u) {
            for (int v = 1; v <= 60; ++v) {
                if (adj[u][v]) {
                    in_degree[v]++;
                }
            }
        }

        queue<int> q;
        for (int u = 1; u <= 60; ++u) {
            if (max_r[u] != -1 && in_degree[u] == 0) {
                q.push(u);
            }
        }

        int count = 0;
        int total_colors = 0;
        for (int u = 1; u <= 60; ++u) {
            if (max_r[u] != -1) total_colors++;
        }

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            count++;
            for (int v = 1; v <= 60; ++v) {
                if (adj[u][v]) {
                    in_degree[v]--;
                    if (in_degree[v] == 0) {
                        q.push(v);
                    }
                }
            }
        }

        return count == total_colors;
    }
};
